<?php require_once 'includes/catalog.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: favoritos.php');exit;}csrf_check();$id=$_POST['content_id']??'';$return=$_POST['return']??'favoritos.php';if(!preg_match('/^[a-zA-Z0-9_-]+\.php(\?.*)?$/',$return))$return='favoritos.php';if(!find_content($id)){flash('Conteúdo inválido.','error');header('Location: '.$return);exit;}$s=db()->prepare('SELECT id FROM favoritos WHERE usuario_id=? AND content_id=?');$s->execute([$_SESSION['user_id'],$id]);if($s->fetch()){$s=db()->prepare('DELETE FROM favoritos WHERE usuario_id=? AND content_id=?');$s->execute([$_SESSION['user_id'],$id]);flash('Conteúdo removido da sua lista.');}else{$s=db()->prepare('INSERT IGNORE INTO favoritos(usuario_id,content_id) VALUES(?,?)');$s->execute([$_SESSION['user_id'],$id]);flash('Adicionado à sua lista!');}header('Location: '.$return);exit;
